from __future__ import annotations

__doc__ = """
Plain-text symbolic backend generation.

The plain backend renders instruction trees into an uppercase, parser-friendly
text format that mirrors the generic code-container structure without targeting
an executable programming language. It is useful for diagnostics, external
tooling, and IR inspection.
"""

